import React, { useContext } from 'react';
import Fade from 'react-reveal/Fade';
import { Container } from 'react-bootstrap';
import { PortfolioContext } from '../../context/context';
import Title from '../Title/Title';

const Experience = () => {
  const { experienceData, isDesktop } = useContext(PortfolioContext);

  return (
    <section id="experience">
      <Container>
        <Title title="Experience" />
        <div className="timeline">
          {experienceData.map((item, idx) => (
            <Fade
              key={item.id}
              left={isDesktop && idx % 2 === 0}
              right={isDesktop && idx % 2 !== 0}
              bottom={!isDesktop}
              duration={800}
              delay={200}
              distance="30px">
              <div className="timeline__item">
                <div className="timeline__dot" />
                <div className="timeline__content">
                  <div className="timeline__header">
                    <h3 className="timeline__school">
                      {item.url ? (
                        <a href={item.url} target="_blank" rel="noopener noreferrer">
                          {item.company}
                        </a>
                      ) : (
                        item.company
                      )}
                    </h3>
                    <span className="timeline__period">{item.period}</span>
                  </div>
                  <p className="timeline__dept">{item.role}</p>
                  <ul className="timeline__details">
                    {item.details.map((d, i) => (
                      <li key={i}>{d}</li>
                    ))}
                  </ul>
                </div>
              </div>
            </Fade>
          ))}
        </div>
      </Container>
    </section>
  );
};

export default Experience;
