import React, { useContext } from 'react';
import Fade from 'react-reveal/Fade';
import { Container, Row } from 'react-bootstrap';
import { PortfolioContext } from '../../context/context';
import Title from '../Title/Title';

const Hero = () => {
  const { heroData, isDesktop } = useContext(PortfolioContext);
  const { title, name, subtitle, cta } = heroData;

  return (
    <section id="hero" className="jumbotron">
      <Container>
        {isDesktop ? (
          <Fade left duration={1000} delay={200} distance="45px">
            <div className="hero-title">
              {title} <span className="hero-name">{name}</span>
              <span className="hero-subtitle">{subtitle}</span>
            </div>
            <div className="hero-cta">
              <a className="cta-btn cta-btn--hero" href="#about">
                {cta}
              </a>
            </div>
          </Fade>
        ) : (
          <Fade bottom duration={1000} delay={200} distance="45px">
            <div className="hero-title">
              {title} <span className="hero-name">{name}</span>
              <span className="hero-subtitle">{subtitle}</span>
            </div>
            <div className="hero-cta">
              <a className="cta-btn cta-btn--hero" href="#about">
                {cta}
              </a>
            </div>
          </Fade>
        )}
      </Container>
    </section>
  );
};

export default Hero;
